SELECT w.id AS wallet_trade_id, w.symbol, w.execution_reason, w.executed_at, s1.id AS s1m_id, s5o.id AS old5_id, s5o.decision AS old5_dec, s5o.atr_immediate_entry_allowed AS old5_atr_imm, s5n.id AS new5_id, s5n.decision AS new5_dec, s5n.final_entry_allowed AS new5_fea, s5n.atr_immediate_entry_allowed AS new5_atr_imm, TIMESTAMPDIFF(MICROSECOND, s1.generated_at, s5n.generated_at) AS new5_after_1m_us, TIMESTAMPDIFF(MICROSECOND, s5n.created_at, w.executed_at) AS new5_saved_before_fill_us, p.id AS paper_id, p.status, p.realized_pnl, p.close_reason FROM wallet_trade w JOIN trade_signal s1 ON s1.id = w.signal_id AND s1.interval_code = '1m' JOIN trade_signal s5n ON s5n.symbol = s1.symbol AND s5n.interval_code = '5m' AND s5n.candle_open_time = s1.candle_open_time - INTERVAL 4 MINUTE LEFT JOIN trade_signal s5o ON s5o.symbol = s1.symbol AND s5o.interval_code = '5m' AND s5o.candle_open_time = s1.candle_open_time - INTERVAL 9 MINUTE LEFT JOIN paper_position p ON p.signal_id = s1.id WHERE w.side = 'BUY' AND w.executed_at >= '2026-10-01 00:00:00' AND MINUTE(s1.candle_open_time) % 5 = 4 AND s5n.generated_at > s1.generated_at AND w.execution_reason <> 'SETUP_CONFIRMATION_WAKEUP' ORDER BY w.executed_at LIMIT 100